/* ======================= v2.14 I18N: the shared-scope language helpers (V214.md 4.2, 5, 8, 11) ======================= */
// The English stays in the code next to its key: tt('walk.home_early', 'Head home early'). The other ten languages come from
// window.PAW_I18N (game/i18n/packed.js, generated by `node tools/i18n_pack.js`): { v, keys: [sorted keys], ja: [text|null per key], ... }.
// Only the current language is turned into a key -> text map, once, at load. A missing or empty text falls back to the English (per key).
// The names below (tt tdata tid tbreed tnum tdate tlist tlang tsetLang) must never be bound anywhere else in game/src: the i18n suite checks.
// Language = the dev/test pin prefs.lang, else S.lang (the player's pick, saved and synced), else (no save yet) the title pick
// prefs.langPick, else PawI18nMsg.pickLang(navigator.languages). Pseudo-locales `xx` (about 40% longer, accented) and `xx-cjk`
// (CJK-shaped) exist only for the tests and the dev panel: they are never in the picker and never saved in S.
const PIM = window.PawI18nMsg || null;
const I18N_CODES = PIM ? PIM.CODES : ['en'];
const I18N_PSEUDO = ['xx', 'xx-cjk'];
const I18N = { lang: 'en', intlDL: 'en-GB', map: null, known: null, misses: [], unknown: [], seen: new Set(), ps: null, intl: 'en', fontCSS: '', fontLang: '' };
const i18nReal = (c) => typeof c === 'string' && I18N_CODES.includes(c);
const i18nPin = () => (prefs && typeof prefs.lang === 'string' && (i18nReal(prefs.lang) || I18N_PSEUDO.includes(prefs.lang)) ? prefs.lang : null);
// the save's language before S is loaded (the HUD and the bar are built before loadSave runs in start())
function i18nSaved() { try { const s = JSON.parse(lsGet(SAVE_KEY) || 'null'); return s && s.v === 1 && (s.dog || (s.dogs && s.dogs.length)) ? { lang: i18nReal(s.lang) ? s.lang : null } : null; } catch (e) { return null; } }
function i18nDevice() { try { return PIM ? PIM.pickLang(navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language]) : 'en'; } catch (e) { return 'en'; } }
// v2.14.2 (owner): the site's language picks the game's. doodledoggo.app opens /play/?lang=<code>; a code the site has not sent before
// wins once (saved as the player's pick, like Settings), so a later pick in Settings keeps until the player changes the site's language.
const I18N_SITE_KEY = 'pawhaven_site_lang';
let i18nUrl = (() => { try { const c = new URLSearchParams(location.search).get('lang'); return i18nReal(c) && lsGet(I18N_SITE_KEY) !== c ? c : null; } catch (e) { return null; } })();
function i18nFromSite() {
  const c = i18nUrl; if (!c) return null;
  if (S) { S.lang = c; markDirty(); } else if (!i18nSaved()) { prefs.langPick = c; savePrefs(); } else return c; // the save loads later: keep it until then
  lsSet(I18N_SITE_KEY, c); i18nUrl = null; return c;
}
function i18nWanted() {
  const pin = i18nPin(); if (pin) return pin;
  const site = i18nFromSite(); if (site) return site;
  const sv = S ? { lang: i18nReal(S.lang) ? S.lang : null } : i18nSaved();
  if (sv) return sv.lang || i18nDevice();
  return i18nReal(prefs.langPick) ? prefs.langPick : i18nDevice();
}
// v2.14 PERF (PERF.md): in the split builds every language but English is its own file (game/i18n/loader.js: PAW_I18N.has / load). The game
// script starts once the wanted language's file came, so this is true at load; when the file failed, the game plays in English (i18nTarget)
// and i18nLater keeps trying: the title screen switches as soon as it comes, in the game it is there on the next load. The single-file
// builds and the test harness carry every language inline: always true.
function i18nHave(code) { const P = window.PAW_I18N; return !(P && P.has) || I18N_PSEUDO.includes(code) || P.has(code); }
function i18nTarget() { const w = i18nWanted(); return i18nHave(w) ? w : 'en'; }
let i18nLaterOn = false;
function i18nLater(code) {
  if (i18nLaterOn) return; i18nLaterOn = true;
  const P = window.PAW_I18N; let n = 0;
  const again = () => P.load(code).then(() => {
    i18nLaterOn = false;
    if (cur.mode === 'title' && i18nTarget() === code && I18N.lang !== code) { i18nApply(code); enterTitle(); }
  }, () => { if (++n < 6) setTimeout(again, 15000 * n); else i18nLaterOn = false; });
  window.addEventListener('online', () => { n = 0; if (!i18nLaterOn) i18nLater(code); }, { once: true }); // back online: six fresh tries
  setTimeout(again, 3000);
}
// build the map for one language (and the known-key set the tests read)
function i18nUse(code) {
  const P = window.PAW_I18N || null;
  I18N.lang = code; I18N.map = null; I18N.known = null; I18N.ps = I18N_PSEUDO.includes(code) ? code : null;
  I18N.intl = code === 'xx' ? 'de' : code === 'xx-cjk' ? 'ja' : code; // pseudo: German numbers and dates (long), Japanese for the CJK one
  I18N.intlDL = I18N.intl === 'en' ? 'en-GB' : I18N.intl; // English dates and lists as the game always wrote them ("Monday 19 October", "A, B and C"); numbers stay en (1,000)
  if (code !== 'en' && P && Array.isArray(P.keys)) {
    if (P.keys.length) I18N.known = new Set(P.keys);
    const arr = !I18N.ps && Array.isArray(P[code]) ? P[code] : null;
    if (arr) { const m = Object.create(null); for (let i = 0; i < arr.length; i++) if (arr[i] != null && arr[i] !== '') m[P.keys[i]] = arr[i]; I18N.map = m; }
  }
  const h = document.documentElement;
  h.lang = code === 'xx' ? 'en-XA' : code === 'xx-cjk' ? 'ja-XA' : code; // CJK glyph shapes, hyphenation and line breaking need it
  if (I18N.ps) h.dataset.pseudo = code; else delete h.dataset.pseudo;
}
function i18nNote(list, key) { const k = list === I18N.misses ? 'm:' + key : 'u:' + key; if (I18N.seen.has(k)) return; I18N.seen.add(k); if (list.length < 5000) list.push(key); }
// tt escapes the vars of `_html` messages itself (V214.md 3.3 rule 7); every other message is plain text the caller escapes
function i18nVars(key, vars) {
  if (!vars || !/_html$/.test(key)) return vars;
  const o = {}; for (const k in vars) o[k] = typeof vars[k] === 'string' ? esc(vars[k]) : vars[k]; return o;
}
function tt(key, en, vars) {
  const L = I18N.lang;
  if (L === 'en') return PIM ? PIM.format(en, i18nVars(key, vars), 'en') : String(en);
  if (I18N.known && !I18N.known.has(key)) i18nNote(I18N.unknown, key); // not in en.json: run `node tools/i18n_extract.js --en` (or a tdata path that TABLES.txt does not give)
  if (I18N.ps) return i18nPseudo(en, i18nVars(key, vars));
  const m = I18N.map && I18N.map[key];
  if (m == null) { i18nNote(I18N.misses, key); return PIM ? PIM.format(en, i18nVars(key, vars), 'en') : String(en); }
  return PIM.format(m, i18nVars(key, vars), L);
}
function tdata(path, en, vars) { return tt('data.' + path, en, vars); }
function tid(s) { return PIM ? PIM.id(s) : String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, ''); }
// the breed name shown: data.breed_names.<key> (the glossary `breeds` fill it in every language), English from mods/genes.js BREED_NAMES
function tbreed(key) { const G = window.PawGenes; return tdata('breed_names.' + key, (G && G.BREED_NAMES && G.BREED_NAMES[key]) || key); }
function tnum(n, opts) { return PIM ? PIM.num(n, I18N.intl, opts) : String(n); }
function tdate(d, opts) { return PIM ? PIM.date(d, I18N.intlDL, opts) : String(d); }
function tlist(arr) { return PIM ? PIM.list(arr, I18N.intlDL) : (arr || []).join(', '); }
function tlang() { return I18N.lang; }

/* ---- the pseudo-locales (tests and the dev panel only): the English message rewritten branch by branch, vars and ICU syntax kept ---- */
const PS_MAP = { a: 'á', b: 'ƀ', c: 'ç', d: 'ð', e: 'é', f: 'ƒ', g: 'ĝ', h: 'ĥ', i: 'í', j: 'ĵ', k: 'ķ', l: 'ľ', m: 'ɱ', n: 'ñ', o: 'ö', p: 'þ', q: 'ǫ', r: 'ŕ', s: 'š', t: 'ŧ', u: 'ü', v: 'ṽ', w: 'ŵ', x: 'ẋ', y: 'ý', z: 'ž',
  A: 'Á', B: 'Ɓ', C: 'Ç', D: 'Ð', E: 'É', F: 'Ƒ', G: 'Ĝ', H: 'Ĥ', I: 'Í', J: 'Ĵ', K: 'Ķ', L: 'Ľ', M: 'Ṁ', N: 'Ñ', O: 'Ö', P: 'Þ', Q: 'Ǫ', R: 'Ŕ', S: 'Š', T: 'Ŧ', U: 'Ü', V: 'Ṽ', W: 'Ŵ', X: 'Ẋ', Y: 'Ý', Z: 'Ž' };
const PS_CJK = 'いぬのさんぽはたのしいねこえきまちこうえんおやつごはんあそびともだちかわいいげんきだよしばいぬくまうみやまかぜはなほしつきあめゆき犬猫柴遊食散歩家庭公園駅町海山空花星月雨雪友達元気';
const PS_CJK_P = { '.': '。', ',': '、', '!': '！', '?': '？', ':': '：', '(': '（', ')': '）' };
function psWord(w, cjk) {
  if (!cjk) return w.replace(/[A-Za-z]/g, (c) => (/[aeiouyAEIOUY]/.test(c) ? PS_MAP[c] + PS_MAP[c.toLowerCase()] : PS_MAP[c])); // vowels doubled: about 40% longer
  let h = 0; for (let i = 0; i < w.length; i++) h = (h * 31 + w.charCodeAt(i)) >>> 0;
  let o = ''; const n = Math.max(1, Math.ceil(w.length * 0.55)); for (let i = 0; i < n; i++) { o += PS_CJK[(h + i * 7) % PS_CJK.length]; }
  return o;
}
function psText(s, cjk) {
  return s.split(/(<[^>]*>|&[#\w]+;)/).map((part, i) => {
    if (i % 2) return part; // a tag or an entity
    let t = part.replace(/[A-Za-z]+/g, (w) => psWord(w, cjk));
    if (cjk) t = t.replace(/[.,!?:()]/g, (c) => PS_CJK_P[c]).replace(/([^\x00-\x7f]) +(?=[^\x00-\x7f])/g, '$1');
    return t;
  }).join('');
}
function psSer(ast, cjk) {
  return ast.map((x) => (typeof x === 'string' ? psText(x, cjk) : x.t === 'hash' ? '#' : x.t === 'arg' ? '{' + x.v + '}' : x.t === 'josa' ? '{' + x.v + ', josa, ' + x.a + '/' + x.b + '}'
    : '{' + x.v + ', ' + x.t + ', ' + Object.keys(x.opts).map((k) => k + ' {' + psSer(x.opts[k], cjk) + '}').join(' ') + '}')).join('');
}
const PS_CACHE = new Map();
function i18nPseudo(en, vars) {
  const cjk = I18N.ps === 'xx-cjk', ck = (cjk ? 'c' : 'x') + en;
  let m = PS_CACHE.get(ck);
  if (m === undefined) {
    try { m = '[' + psSer(PIM.parse(String(en)), cjk) + ']'; } catch (e) { m = '[' + psText(String(en), cjk) + ']'; }
    if (PS_CACHE.size > 8000) PS_CACHE.clear(); PS_CACHE.set(ck, m);
  }
  return PIM.format(m, vars, 'en');
}

/* ---- the fonts (docs/i18n/FONTS.md section 5): only the current language's 'DD Local' face, from fonts/i18n/<file> next to the page ----
   window.PAW_I18N.fonts = { ja: [{ f: 'DD Local', u: 'ja.woff2?v=1a2b3c4d', r: 'U+3001-3002,...' }], ... } (tools/i18n_pack.js reads game/fonts/i18n/<lang>.css).
   Under the test harness (navigator.webdriver) nothing is fetched unless a suite sets prefs.i18nFonts: file:// pages cannot load fonts. */
const I18N_FONT_DIR = 'fonts/i18n/';
function i18nFonts(code) {
  const P = window.PAW_I18N, list = P && P.fonts && P.fonts[code];
  I18N.fontCSS = ''; I18N.fontLang = code;
  if (!list || !list.length || typeof FontFace !== 'function' || !document.fonts || (navigator.webdriver && !prefs.i18nFonts)) return;
  const css = [];
  list.forEach((x) => {
    fetch(I18N_FONT_DIR + x.u).then((r) => (r.ok ? r.arrayBuffer() : Promise.reject(new Error('font ' + r.status)))).then((buf) => {
      if (I18N.fontLang !== code) return;
      const face = new FontFace(x.f, buf, { unicodeRange: x.r, display: 'swap', weight: '400 700' });
      document.fonts.add(face);
      // the photo postcard draws an SVG on a canvas, which cannot reach page fonts: keep the same bytes as a data URI (tfontCSS)
      let bin = ''; const b = new Uint8Array(buf); for (let i = 0; i < b.length; i += 0x8000) bin += String.fromCharCode.apply(null, b.subarray(i, i + 0x8000));
      css.push(`@font-face{font-family:'${x.f}';font-weight:400 700;src:url(data:font/woff2;base64,${btoa(bin)}) format('woff2');unicode-range:${x.r}}`);
      I18N.fontCSS = css.join('');
    }).catch(() => { /* offline, or a single-file copy without the side files: the system fonts in the CSS stack take over */ });
  });
}
// the current language's faces as @font-face CSS with data URIs, for the photo postcard (35_photo.js puts it next to PH_FONT_CSS). '' for English,
// the Latin languages, before the face has arrived, or under the harness.
function tfontCSS() { return I18N.fontLang === I18N.lang ? I18N.fontCSS : ''; }

/* ---- switching (V214.md 5) ---- */
// a walk, a trick game, cooking or ball play: the picker waits ("You can change the language at home.")
function tlangBusy() {
  const m = cur.mode;
  if (['walk', 'fetch', 'toy', 'kitchen'].includes(m)) return true;
  if (typeof TRN !== 'undefined' && TRN && TRN.game) return true;
  return typeof blOn === 'function' && !!blOn();
}
const tlangBusyText = () => tt('settings.lang_busy', 'You can change the language at home.');
// shell text that is in game/shell.html (the HUD buttons, the stage label): set again in the current language
function i18nShell() {
  const set = (sel, attr, text) => { const e = document.querySelector(sel); if (e) e.setAttribute(attr, text); };
  set('#stage', 'aria-label', tt('shell.stage_label', 'Doodle Doggo game'));
  set('#hud .bond', 'title', tt('shell.bond_title', 'Bond level'));
  set('#bondTrack', 'aria-label', tt('shell.bond_progress', 'Bond progress'));
  set('#coins', 'title', tt('shell.coins_title', 'Paw Coins'));
  set('#gearBtn', 'aria-label', tt('shell.settings', 'Settings'));
  set('#moreBtn', 'aria-label', tt('shell.menu', 'Menu: settings and sound'));
  set('#trainPanel', 'aria-label', tt('shell.training', 'Trick training'));
  set('#bar', 'aria-label', tt('shell.actions', 'Actions'));
  const lb = document.querySelector('#hud .bond .lbl'); if (lb && lb.firstChild && lb.firstChild.nodeType === 3) lb.firstChild.nodeValue = tt('shell.bond', 'Bond') + ' ';
  if (I18N.lang !== 'en') document.title = tt('shell.title', 'Doodle Doggo');
  if (S && !I18N.ps && i18nReal(code) && S.langShown !== code) { S.langShown = code; markDirty(); } // v2.15 (owner): S.langShown = the language on screen
}
// tsetLang(code): code is one of the 11 CODES, or null = follow the device. Returns false when it cannot switch now.
// On the title screen it re-renders live; in the game it saves and reloads (every screen rebuilds from S, nothing stale stays).
function tsetLang(code, o) {
  o = o || {};
  if (code != null && !i18nReal(code) && !(o.pseudo && I18N_PSEUDO.includes(code))) return false;
  if (tlangBusy()) { toast(tlangBusyText()); return false; }
  const pseudo = I18N_PSEUDO.includes(code), need = code == null ? i18nDevice() : code;
  if (!pseudo && !i18nHave(need)) { // split builds: fetch the language's file first, then switch (nothing changes when it fails)
    window.PAW_I18N.load(need).then(() => tsetLang(code, o), () => toast(tt('cloud.err_generic', "That didn't work. Try again in a moment.")));
    return true;
  }
  if (S && !pseudo) { S.lang = code; markDirty(); }
  else if (!S && !pseudo) prefs.langPick = code;
  if (pseudo || 'lang' in prefs) prefs.lang = code; // a pin (the harness, the dev panel) follows the pick, so a reload keeps it
  savePrefs();
  const next = i18nWanted();
  if (!S || cur.mode === 'title') { if (S) saveNow(); i18nApply(next); if (cur.mode === 'title') enterTitle(); return true; }
  i18nReload(); return true;
}
// in the game a switch saves and reloads; boot goes straight back to the yard (23_boot.js reads the flag), not to the title screen
const I18N_RELOAD = 'pawhaven_lang_reload';
function i18nReload() { saveNow(); try { sessionStorage.setItem(I18N_RELOAD, '1'); } catch (e) { /* storage blocked: boot shows the title */ } location.reload(); }
function i18nReloaded() { try { const v = sessionStorage.getItem(I18N_RELOAD); sessionStorage.removeItem(I18N_RELOAD); return v === '1'; } catch (e) { return false; } }
function i18nApply(code) {
  i18nUse(code); i18nFonts(code); i18nShell();
  try { buildHUD(); barLabels(); if (S) updateHUD(); } catch (e) { /* before the HUD exists */ }
}
// the language a cloud save brought (22b_cloud.js applies saves): when it differs from the one on screen, reload into it
function tlangCheck() {
  const w = i18nWanted();
  if (!i18nHave(w)) { window.PAW_I18N.load(w).then(() => tlangCheck(), () => i18nLater(w)); return false; } // split builds: its file first
  if (w === I18N.lang) return false; if (!S || cur.mode === 'title') { i18nApply(w); if (cur.mode === 'title') enterTitle(); return true; } i18nReload(); return true; }
// the test hook, inside window.__paw (23_boot.js): { lang, misses, unknown, set(code) } (set accepts the pseudo-locales too)
const I18N_HOOK = { get lang() { return I18N.lang; }, get misses() { return I18N.misses.slice(); }, get unknown() { return I18N.unknown.slice(); }, get codes() { return I18N_CODES.slice(); },
  set: (code) => tsetLang(code, { pseudo: true }), clear: () => { I18N.misses.length = 0; I18N.unknown.length = 0; I18N.seen.clear(); }, fontCSS: () => tfontCSS(), wanted: () => i18nWanted() };

i18nUse(i18nTarget()); i18nFonts(I18N.lang);
if (I18N.lang !== i18nWanted()) i18nLater(i18nWanted());
window.PawI18n = { tt, tdata, tbreed, tnum, tdate, tlist, tlang };
